复杂的查询大概是这样子写：

query CustomerDetail(customer: CustomerId) {
    from customers as c
    where c.id == $customer

    select {
        id:   c.id,
        name: c.name,

        addresses: many {
            from addresses as a
            where a.customer_id == c.id

            select {
                id:      a.id,
                city:    a.city,
                address: a.address
            }
        },

        orders: many {
            from orders as o
            where o.customer_id == c.id

            select {
                id:         o.id,
                created_at: o.created_at,
                total:      o.total,

                items: many {
                    from order_items as oi

                    join products as p
                        on p.id == oi.product_id

                    where oi.order_id == o.id

                    select {
                        product: {
                            id:   p.id,
                            name: p.name
                        },

                        quantity: oi.quantity,
                        price:    oi.price
                    }
                }
            }

            order {
                o.created_at desc
            }

            limit 20
        }
    }
}

